function configurarEventosDoFormulario(){const e=document.getElementById("form-cadastro");e&&e.addEventListener("submit",e=>{e.preventDefault();const o=document.getElementById("nome-usuario").value,t=validarNome(o);t.valido?(Swal.fire({title:"Tudo Certo!",text:t.mensagem,icon:"success",confirmButtonColor:"#3085d6"}),salvarUsuario(o),document.getElementById("nome-usuario").value=""):Swal.fire({title:"Atenção!",text:t.mensagem,icon:"error",confirmButtonColor:"#d33"})})}import{navegarPara}from"./modules/router.js";import{validarNome}from"./modules/validation.js";import{salvarUsuario}from"./modules/storage.js";document.addEventListener("DOMContentLoaded",()=>{navegarPara("home")}),document.getElementById("nav-home").addEventListener("click",()=>{navegarPara("home")}),document.getElementById("nav-form").addEventListener("click",()=>{navegarPara("form"),configurarEventosDoFormulario()});